import Link from "next/link";

export default function HomePage() {
  const features = [
    {
      title: "Create Service Jobs",
      description:
        "Create, assign and manage service requests from one centralized platform.",
      icon: "📋",
    },
    {
      title: "Technician Assignment",
      description:
        "Assign technicians based on availability and monitor progress.",
      icon: "👨‍🔧",
    },
    {
      title: "Live Status Tracking",
      description:
        "Track every work order from Open to Completed in real time.",
      icon: "📍",
    },
    {
      title: "Customer Records",
      description:
        "Maintain searchable customer profiles and service history.",
      icon: "👥",
    },
    {
      title: "Analytics Dashboard",
      description:
        "View work orders, technicians and performance metrics instantly.",
      icon: "📊",
    },
    {
      title: "Secure Access",
      description:
        "Role-based authentication for Admins, Dispatchers and Technicians.",
      icon: "🔐",
    },
  ];

  return (
    <main className="min-h-screen bg-white text-slate-900">
      <header className="sticky top-0 z-50 border-b bg-white/90 backdrop-blur">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-6 py-4">
          <Link href="/" className="text-2xl font-bold text-blue-600">
            FieldFlow
          </Link>

          <nav className="hidden gap-8 md:flex">
            <a href="#features" className="hover:text-blue-600">Features</a>
            <a href="#how" className="hover:text-blue-600">How It Works</a>
            <a href="#about" className="hover:text-blue-600">About</a>
            <a href="#contact" className="hover:text-blue-600">Contact</a>
          </nav>

          <div className="flex gap-3">
            <Link href="/login" className="rounded-lg border border-blue-600 px-5 py-2 text-blue-600 hover:bg-blue-50">
              Login
            </Link>
            <Link href="/register" className="rounded-lg bg-blue-600 px-5 py-2 text-white hover:bg-blue-700">
              Get Started
            </Link>
          </div>
        </div>
      </header>

      <section className="mx-auto grid max-w-7xl gap-12 px-6 py-24 lg:grid-cols-2 lg:items-center">
        <div>
          <span className="rounded-full bg-blue-100 px-4 py-2 text-sm font-semibold text-blue-700">
            Modern Field Service Management
          </span>
          <h1 className="mt-6 text-5xl font-extrabold leading-tight">
            Manage Field Service Operations Faster and Smarter
          </h1>
          <p className="mt-6 text-lg text-slate-600">
            Create service jobs, assign technicians, monitor progress, manage
            customers and make better business decisions from one powerful platform.
          </p>
          <div className="mt-10 flex gap-4">
            <Link href="/register" className="rounded-xl bg-blue-600 px-8 py-4 font-semibold text-white">
              Get Started
            </Link>
            <Link href="/login" className="rounded-xl border px-8 py-4 font-semibold">
              Login
            </Link>
          </div>
        </div>

        <div className="rounded-3xl bg-slate-100 p-8 shadow-xl">
          <div className="grid grid-cols-2 gap-4">
            {[
              ["Open Jobs", "128"],
              ["Technicians", "42"],
              ["Customers", "1,250"],
              ["Completion", "98%"],
            ].map(([t, v]) => (
              <div key={t} className="rounded-xl bg-white p-6 shadow">
                <p className="text-sm text-slate-500">{t}</p>
                <h3 className="mt-2 text-3xl font-bold text-blue-600">{v}</h3>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section id="features" className="bg-slate-50 py-20">
        <div className="mx-auto max-w-7xl px-6">
          <h2 className="text-center text-4xl font-bold">Why Choose FieldFlow?</h2>
          <p className="mx-auto mt-4 max-w-3xl text-center text-slate-600">
            Everything you need to manage field operations efficiently.
          </p>

          <div className="mt-14 grid gap-8 md:grid-cols-2 lg:grid-cols-3">
            {features.map((f) => (
              <div key={f.title} className="rounded-2xl bg-white p-8 shadow transition hover:-translate-y-1 hover:shadow-lg">
                <div className="text-4xl">{f.icon}</div>
                <h3 className="mt-5 text-xl font-bold">{f.title}</h3>
                <p className="mt-3 text-slate-600">{f.description}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section id="how" className="py-20">
        <div className="mx-auto max-w-6xl px-6">
          <h2 className="text-center text-4xl font-bold">How It Works</h2>
          <div className="mt-14 grid gap-8 md:grid-cols-4">
            {[
              "Customer submits request",
              "Dispatcher creates work order",
              "Technician completes service",
              "Manager reviews dashboard",
            ].map((s, i) => (
              <div key={s} className="text-center">
                <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-blue-600 text-2xl font-bold text-white">{i + 1}</div>
                <p className="mt-5 font-semibold">{s}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      <section className="bg-blue-600 py-20 text-center text-white">
        <h2 className="text-4xl font-bold">Ready to Transform Your Field Operations?</h2>
        <p className="mx-auto mt-4 max-w-2xl text-blue-100">
          Join FieldFlow and simplify service management from request to completion.
        </p>
        <Link href="/register" className="mt-8 inline-block rounded-xl bg-white px-8 py-4 font-semibold text-blue-600">
          Start Free
        </Link>
      </section>

      <footer id="contact" className="bg-slate-900 py-8 text-center text-slate-400">
        <h3 className="text-xl font-bold text-white">FieldFlow</h3>
        <p className="mt-2">© 2026 FieldFlow. All rights reserved.</p>
      </footer>
    </main>
  );
}